/** Build the preset for one calendar year (used by the year dropdown). */
export function yearPreset(year: number): Preset {
  return {
    id: `${YEAR_PRESET_PREFIX}${year}`,
    label: `Jahr ${year}`,
    range: { kind: 'year', year },
    bucket: '1d',
    fields: ['temp_inside', 'temp_outside'],
  };
}

/**
 * Resolve a stored preset id. Returns null when the id is neither a known
 * preset nor a well-formed "year-YYYY" id.
 */
export function presetForId(id: string | null): Preset | null {
  if (!id) return null;

  const known = PRESETS.find((preset) => preset.id === id);
  if (known) return known;

  if (id.startsWith(YEAR_PRESET_PREFIX)) {
    const year = Number(id.slice(YEAR_PRESET_PREFIX.length));
    if (Number.isInteger(year) && year >= 1900 && year <= 2200) {
      return yearPreset(year);
    }
  }

  return null;
}

/** The default preset; falls back to the first entry when it is missing. */
export function defaultPreset(): Preset {
  const preset = presetForId(DEFAULT_PRESET_ID) ?? PRESETS[0];
  if (!preset) throw new Error('PRESETS is empty');
  return preset;
}

/** API parameters of a preset window. */
export interface SeriesWindow {
  hours?: number;
  from?: string;
  to?: string;
}

/**
 * Turn a preset range into api/series.php parameters.
 *
 * `currentYear` comes from the API (the database clock), not from the browser:
 * the dataset uses the Pi's local wall clock, so the year boundary must be the
 * one the server considers current.
 */
export function resolveRange(range: PresetRange, currentYear: number): SeriesWindow {
  switch (range.kind) {
    case 'hours':
      return { hours: range.hours };
    case 'year':
      return { from: `${range.year}-01-01`, to: `${range.year}-12-31 23:59:59` };
    case 'currentYear':
      return { from: `${currentYear}-01-01` };
    case 'all':
      return {};
  }
}
